const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function productArt(p){let shape=''; const c=p.color;switch(p.kind){
 case 'headphones':shape=`<path d="M61 95V75a39 39 0 0 1 78 0v20" fill="none" stroke="#10141a" stroke-width="19"/><path d="M61 92V75a39 39 0 0 1 78 0v17" fill="none" stroke="${c}" stroke-width="12"/><rect x="48" y="82" width="25" height="49" rx="11" fill="${c}" transform="rotate(-8 61 105)"/><rect x="127" y="82" width="25" height="49" rx="11" fill="${c}" transform="rotate(8 140 105)"/><rect x="55" y="87" width="9" height="38" rx="4" fill="#333b46" opacity=".7"/><rect x="136" y="87" width="9" height="38" rx="4" fill="#333b46" opacity=".7"/>`;break;
 case 'earbuds':shape=`<rect x="57" y="83" width="86" height="55" rx="24" fill="${c}"/><path d="M58 100h84" stroke="#68737b" opacity=".4"/><path d="M78 78V55c-14-4-10-24 2-24 15 0 17 17 7 23v24z M116 78V55c14-4 10-24-2-24-15 0-17 17-7 23v24z" fill="${c}"/><circle cx="100" cy="115" r="2" fill="#808b8c"/>`;break;
 case 'speaker':shape=`<rect x="61" y="48" width="78" height="88" rx="21" fill="${c}"/><rect x="67" y="62" width="66" height="63" rx="15" fill="#465e57" opacity=".5"/><path d="M74 73h52 M74 80h52 M74 87h52 M74 94h52 M74 101h52 M74 108h52 M74 115h52" stroke="#182d29" stroke-width="2" opacity=".25"/><path d="M87 43v-8a13 13 0 0 1 26 0v8" fill="none" stroke="${c}" stroke-width="5"/>`;break;
 case 'camera':shape=`<rect x="44" y="63" width="112" height="68" rx="12" fill="${c}"/><rect x="48" y="78" width="104" height="46" rx="7" fill="#45505a"/><circle cx="104" cy="97" r="30" fill="#2c333b"/><circle cx="104" cy="97" r="23" fill="#101c2a"/><circle cx="104" cy="97" r="16" fill="#263d51"/><circle cx="98" cy="91" r="7" fill="#92c6cb" opacity=".4"/><rect x="60" y="55" width="20" height="8" rx="3" fill="${c}"/><rect x="54" y="69" width="19" height="7" rx="2" fill="#f4f2da"/>`;break;
 case 'bag':shape=`<path d="M58 61h84l10 76H48z" fill="${c}"/><path d="M78 69V45c0-29 44-29 44 0v24" stroke="#b2a38c" stroke-width="8" fill="none"/><path d="M60 72h80 M62 128h76" stroke="#b5a78f" stroke-width="1"/><path d="M85 92h30v18H85z" fill="#a99579" opacity=".7"/>`;break;
 case 'charger':shape=`<rect x="65" y="31" width="70" height="111" rx="13" fill="${c}"/><rect x="73" y="40" width="54" height="17" rx="5" fill="#394656"/><text x="100" y="52" fill="#b4dce1" font-size="9" text-anchor="middle">100</text><path d="m103 77-13 20h12l-4 20 15-25h-12z" fill="#67788c"/><rect x="87" y="135" width="26" height="3" rx="1" fill="#273746"/>`;break;
 case 'lamp':shape=`<path d="M100 78v56 M79 137h42" fill="none" stroke="${c}" stroke-width="7" stroke-linecap="round"/><path d="M67 79c0-62 66-62 66 0z" fill="${c}"/><ellipse cx="100" cy="79" rx="33" ry="7" fill="#f4e4b2"/><ellipse cx="100" cy="137" rx="31" ry="7" fill="${c}"/>`;break;
 }return `<div class="product-art" role="img" aria-label="${escape(p.name)}"><svg viewBox="0 0 200 170"><defs><radialGradient id="bg-${p.id}"><stop stop-color="#3e4854"/><stop offset="1" stop-color="#252c34"/></radialGradient></defs><rect width="200" height="170" fill="url(#bg-${p.id})"/><ellipse cx="101" cy="145" rx="51" ry="7" fill="#0d141b" opacity=".35"/>${shape}</svg></div>`;}
